<?php
require_once 'includes/auth.php';
require_once '../includes/volunteers.php';
$language=($_GET['lang'] ?? $_POST['lang'] ?? $_SESSION['volunteer_language'] ?? 'ms')==='en'?'en':'ms'; $t=static fn($ms,$en)=>$language==='en'?$en:$ms; $error='';
if ($_SERVER['REQUEST_METHOD']==='POST') { try { verifyVolunteerCsrf($_POST['csrf_token']??null); $password=(string)($_POST['password']??''); if(strlen($password)<12 || !preg_match('/[A-Z]/',$password) || !preg_match('/[a-z]/',$password) || !preg_match('/\d/',$password)){throw new RuntimeException($t('Kata laluan mesti sekurang-kurangnya 12 aksara dan mengandungi huruf besar, huruf kecil serta nombor.','Password must be at least 12 characters and contain uppercase, lowercase, and a number.'));} if($password!==($_POST['confirm_password']??'')){throw new RuntimeException($t('Pengesahan kata laluan tidak sepadan.','Password confirmation does not match.'));} $stmt=$pdo->prepare('UPDATE users SET password=?, must_change_password=0 WHERE id=?'); $stmt->execute([password_hash($password,PASSWORD_DEFAULT),$currentUser['id']]); recordActivity($pdo,'volunteer_password_changed','user',(int)$currentUser['id'],'Volunteer changed password.',[],(int)$currentUser['id'],'volunteer',(string)$currentUser['username']); header('location: dashboard.php?lang='.$language); exit; } catch(Throwable $e){$error=$e->getMessage();}}
$pageTitle=$t('Tukar Kata Laluan','Change Password'); require 'includes/header.php'; ?>
<div class="card mx-auto" style="max-width:560px"><div class="card-body p-4 p-md-5"><h1 class="h3"><?php echo $t('Tetapkan kata laluan baharu','Set a new password'); ?></h1><p class="text-muted"><?php echo $t('Anda mesti menggantikan kata laluan sementara sebelum meneruskan.','You must replace your temporary password before continuing.'); ?></p><?php if($error):?><div class="alert alert-danger"><?php echo htmlspecialchars($error); ?></div><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars(volunteerCsrfToken()); ?>"><input type="hidden" name="lang" value="<?php echo $language; ?>"><div class="mb-3"><label class="form-label"><?php echo $t('Kata laluan baharu','New password'); ?></label><input class="form-control" type="password" name="password" autocomplete="new-password" required></div><div class="mb-4"><label class="form-label"><?php echo $t('Sahkan kata laluan','Confirm password'); ?></label><input class="form-control" type="password" name="confirm_password" autocomplete="new-password" required></div><button class="btn btn-primary w-100" style="background:#004a99"><?php echo $t('Simpan kata laluan','Save password'); ?></button></form></div></div><?php require 'includes/footer.php'; ?>
